jQuery(document).ready(function($){"use strict";function upload_image(){var affi_img_uploader;$(document).on("click",".affi-upload-badge-remove",function(){let wrap=$(this).closest(".affi-upload-badge-wrap");let src_placeholder=wrap.find(".affi-upload-badge-preview img").data("src_placeholder");wrap.find(".affi-rank-badge").val("");wrap.find(".affi-upload-badge-preview img").attr("src",src_placeholder);$(this).addClass("affi-hidden")});$(document).on("click",".affi-upload-badge-add-new",function(e){e.preventDefault();$(this).closest(".affi-upload-badge-wrap").addClass("affi-upload-img-editing");let editing=$(".affi-upload-img-editing");if(affi_img_uploader){affi_img_uploader.open();return false}affi_img_uploader=wp.media.frames.file_frame=wp.media({title:"Choose Badge",button:{text:"Choose Badge"},multiple:true});affi_img_uploader.on("select",function(){let attachment=affi_img_uploader.state().get("selection").first().toJSON();editing.find(".affi-rank-badge").val(attachment.id);editing.find(".affi-upload-badge-preview img").attr("src",attachment.url);editing.find(".affi-upload-badge-remove").removeClass("affi-hidden");editing.removeClass("affi-upload-img-editing")});affi_img_uploader.open()})}$(".affi-dropdown").each(function(){let placeholder=$(this).attr("placeholder");$(this).viDropdown({placeholder:placeholder})});upload_image()});